#include "../Drivers/rcc/rcc.h"
#include "../Drivers/gpio/gpio.h"
#include "../Drivers/timer/timer.h"

int main (void)
{
    rcc_init();
    gpio_init();
    timer_init();

    while(1)
    {
        /* Reset PA9 PA10 */
        GPIOA->BSRR = (3UL << 25U);
        delay_ms(1000);

        /* Set PA9 PA10 */
        GPIOA->BSRR = (3UL << 9U);
        delay_ms(1000);
    }


}

